<?php
require_once __DIR__ . '/../includes/functions.php'; require_role(['admin','staff','cashier']);
$q=trim($_GET['q']??'');$like='%'.$q.'%';$s=$conn->prepare('SELECT id,product_code,name,selling_price,stock_quantity FROM products WHERE is_active=1 AND (name LIKE ? OR product_code LIKE ?) ORDER BY name LIMIT 100');$s->bind_param('ss',$like,$like);$s->execute();$products=$s->get_result()->fetch_all(MYSQLI_ASSOC);
layout_header('Point of sale');
?>
<div class="grid two section-gap"><section class="card"><h2>Find a product</h2><form method="get" class="search-form"><input name="q" placeholder="Product name or code" value="<?= e($q) ?>"><button class="btn">Search</button></form><div class="product-pick-list"><?php foreach($products as $p): ?><div class="pick-item"><div><b><?= e($p['name']) ?></b><small><?= e($p['product_code']) ?> · <?= (int)$p['stock_quantity'] ?> in stock</small></div><strong><?= money((float)$p['selling_price']) ?></strong><button class="btn btn-small add-to-cart" type="button" <?= (int)$p['stock_quantity'] < 1 ? 'disabled aria-label="Out of stock"' : '' ?> data-id="<?= $p['id'] ?>" data-code="<?= e($p['product_code']) ?>" data-name="<?= e($p['name']) ?>" data-price="<?= e((string)$p['selling_price']) ?>" data-stock="<?= $p['stock_quantity'] ?>"><?= (int)$p['stock_quantity'] < 1 ? 'Out of stock' : 'Add' ?></button></div><?php endforeach; if(!$products) echo '<p class="muted">No matching products. Try a different name or product code.</p>'; ?></div></section>
<section class="card"><h2>Current sale</h2><form method="post" action="<?= BASE_URL ?>/cashier/checkout.php" id="checkoutForm"><?= csrf_field() ?><div id="cartRows" class="cart-rows" aria-live="polite"><p class="muted">No items yet. Add products from the list.</p></div><div class="checkout-summary"><div><span>Total</span><strong id="cartTotal" aria-live="polite">₱0.00</strong></div><label>Payment received (₱)<input type="number" name="payment" id="payment" step=".01" min="0" required></label><div><span>Change</span><strong id="changeAmount" aria-live="polite">₱0.00</strong></div></div><input type="hidden" name="cart_json" id="cartJson"><button class="btn full" id="completeSale" disabled>Complete sale</button></form></section></div>
<?php layout_footer(); ?>
